package com.servicerca.repository; import com.servicerca.model.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import jakarta.persistence.LockModeType;import java.util.*;
public interface ServiceRequestRepository extends JpaRepository<ServiceRequest,UUID>{List<ServiceRequest> findByClientIdAndDeletedAtIsNullOrderByCreatedAtDesc(UUID id);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select r from ServiceRequest r where r.id=:id")Optional<ServiceRequest> findLocked(@Param("id")UUID id);@Query("select r from ServiceRequest r where lower(r.locality)=lower(:locality) and r.trade in :trades and r.status in :states and r.client.id<>:userId")List<ServiceRequest> findFeed(@Param("userId")UUID userId,@Param("locality")String locality,@Param("trades")Set<Trade> trades,@Param("states")Set<RequestStatus> states);}
